import{_ as r,o,c as t,a0 as s}from"./chunks/framework.ChlVJx0I.js";const u=JSON.parse('{"title":"Per-worktree index, seeded from a sibling worktree","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0002-per-worktree-index-seeded-from-sibling.md","filePath":"adr/0002-per-worktree-index-seeded-from-sibling.md","lastUpdated":1788385254000}'),i={name:"adr/0002-per-worktree-index-seeded-from-sibling.md"};function n(a,e,d,l,c,h){return o(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="per-worktree-index-seeded-from-a-sibling-worktree" tabindex="-1">Per-worktree index, seeded from a sibling worktree <a class="header-anchor" href="#per-worktree-index-seeded-from-a-sibling-worktree" aria-label="Permalink to &quot;Per-worktree index, seeded from a sibling worktree&quot;">​</a></h1><p>A git worktree holds a different branch, so a shared codegraph index would answer queries with another branch&#39;s symbols. Upstream codegraph calls this the &quot;borrowed index&quot; problem and its only built-in fix is a full reindex per worktree (<code>codegraph init -i</code>), which the user rejected as too slow. We decided: every worktree owns its own index, and a new worktree&#39;s index is <strong>seeded</strong> by copying a sibling worktree&#39;s <code>codegraph.db</code> (SQLite online backup), followed by one <strong>reconcile</strong> pass that re-extracts only the files that actually differ on this branch.</p><h2 id="why-seeding-works" tabindex="-1">Why seeding works <a class="header-anchor" href="#why-seeding-works" aria-label="Permalink to &quot;Why seeding works&quot;">​</a></h2><p>Codegraph stores file paths relative to the project root and keys files by content hash. Git checkout rewrites mtime on every file it writes, so after a seed the reconcile&#39;s size/mtime pre-filter lets every file through to the hash check, and only genuinely changed files are re-extracted. The seeded index therefore converges to the exact state a from-scratch build would reach, at the cost of one file copy plus a read/hash pass.</p><h2 id="considered-options" tabindex="-1">Considered Options <a class="header-anchor" href="#considered-options" aria-label="Permalink to &quot;Considered Options&quot;">​</a></h2><ul><li><strong>Per-worktree index with sibling seed (chosen).</strong> Per-branch truth, no full rebuild, and it matches upstream&#39;s own model: a worktree-local index is the blessed state, so upstream&#39;s borrowed-index warning never fires.</li><li><strong>One shared index for the repo</strong> (stored outside the trees, e.g. next to the common <code>.git</code>). One build total, but the graph reflects only one branch. Queries from any other worktree return wrong-branch symbols, which the model would cite confidently. Rejected on correctness.</li><li><strong>Symlink <code>.codegraph</code> into new worktrees.</strong> Same wrong-branch problem as sharing, plus it breaks the daemon lockfile and codegraph&#39;s inode-replacement detection. Rejected.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>Sibling discovery is git-native (<code>git worktree list</code> plus the shared common git dir). Worktrees created anywhere - herdr under <code>~/.herdr/worktrees/</code>, PR checkouts under <code>/tmp/</code>, hand-made - need no special casing.</li><li>Seed source: prefer the main worktree if it has an index, otherwise any indexed sibling; a partial (incomplete) sibling index is accepted because the post-seed reconcile is a full file walk and converges either way.</li><li>The create-or-seed decision happens under codegraph&#39;s per-root <code>FileLock</code>, so two concurrent sessions in the same new worktree build once.</li><li>Diverged branches pay &quot;re-extract only the diff&quot;. If a repo grows branches that differ by thousands of files, the seed source can be refined to the closest-HEAD sibling; not done until measured.</li></ul>',8)])])}const w=r(i,[["render",n]]);export{u as __pageData,w as default};
